import { test, expect } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../auth/user.json') });

test.describe('Наведение камеры', () => {
  test('Норма: «כל הבריכה בתמונה», «המשך» активна и ведёт к детям #7076cfab @iphone @prod-safe', async ({ page }) => {
    // 1. Подготовка с ?mock=calm до шага камеры.
    await page.goto('/home?mock=calm');
    await page.getByRole('button', { name: 'התחלת ניטור' }).click();
    await page.getByRole('button', { name: 'עוצמת צפצוף מקסימלית' }).click();
    await page.getByRole('button', { name: 'השמעה' }).click();
    await page.getByRole('button', { name: 'שמעתי' }).click();
    await page.getByRole('button', { name: 'המשך' }).click();
    await page.waitForURL(/\/monitor\/camera/);

    // 2. Проверить заголовок, шаг и подсказку.
    await expect(page.getByText('שלב 2 מתוך 3')).toBeVisible();
    await expect(page.getByRole('heading', { name: 'כוונו את המצלמה לבריכה' })).toBeVisible();
    await expect(page.getByText('בדפדפן מוצגת תמונה לדוגמה')).toBeVisible();
    await expect(page.getByText('כל הבריכה בתמונה')).toBeVisible();

    // 3. Нажать «המשך».
    const continueButton = page.getByRole('button', { name: 'המשך' });
    await expect(continueButton).not.toHaveAttribute('aria-disabled', 'true');
    await continueButton.click();
    await page.waitForURL(/\/monitor\/children/);
    await expect(page.getByRole('heading', { name: 'מי בבריכה היום?' })).toBeVisible();
  });
});
